class Solution {
    private long[] p;
    private long[] h;

    public String longestDupSubstring(String s) {
        int base = 131;
        int n = s.length();
        p = new long[n + 10];
        h = new long[n + 10];
        p[0] = 1;
        for (int i = 0; i < n; ++i) {
            p[i + 1] = p[i] * base;
            h[i + 1] = h[i] * base + s.charAt(i);
        }
        String ans = "";
        int left = 0, right = n;
        while (left < right) {
            int mid = (left + right + 1) >> 1;
            String t = check(s, mid);
            if (t.length() > 0) {
                left = mid;
                ans = t;
            } else {
                right = mid - 1;
            }
        }
        return ans;
    }

    private String check(String s, int len) {
        int n = s.length();
        Set<Long> vis = new HashSet<>();
        for (int i = 1; i + len - 1 <= n; ++i) {
            int j = i + len - 1;
            long t = h[j] - h[i - 1] * p[j - i + 1];
            if (vis.contains(t)) {
                return s.substring(i - 1, j);
            }
            vis.add(t);
        }
        return "";
    }
}

typedef unsigned long long ULL;

class Solution {
public:
    ULL p[30010];
    ULL h[30010];
    string longestDupSubstring(string s) {
        int base = 131, n = s.size();
        p[0] = 1;
        for (int i = 0; i < n; ++i) {
            p[i + 1] = p[i] * base;
            h[i + 1] = h[i] * base + s[i];
        }
        int left = 0, right = n;
        string ans = "";
        while (left < right) {
            int mid = (left + right + 1) >> 1;
            string t = check(s, mid);
            if (t.empty())
                right = mid - 1;
            else {
                left = mid;
                ans = t;
            }
        }
        return ans;
    }

    string check(string& s, int len) {
        int n = s.size();
        unordered_set<ULL> vis;
        for (int i = 1; i + len - 1 <= n; ++i) {
            int j = i + len - 1;
            ULL t = h[j] - h[i - 1] * p[j - i + 1];
            if (vis.count(t)) return s.substr(i - 1, len);
            vis.insert(t);
        }
        return "";
    }
};

func longestDupSubstring(s string) string {
	base, n := 131, len(s)
	p := make([]int64, n+10)
	h := make([]int64, n+10)
	p[0] = 1
	for i := 0; i < n; i++ {
		p[i+1] = p[i] * int64(base)
		h[i+1] = h[i]*int64(base) + int64(s[i])
	}
	check := func(l int) string {
		vis := make(map[int64]bool)
		for i := 1; i+l-1 <= n; i++ {
			j := i + l - 1
			t := h[j] - h[i-1]*p[j-i+1]
			if vis[t] {
				return s[i-1 : j]
			}
			vis[t] = true
		}
		return ""
	}
	left, right := 0, n
	ans := ""
	for left < right {
		mid := (left + right + 1) >> 1
		t := check(mid)
		if len(t) > 0 {
			left = mid
			ans = t
		} else {
			right = mid - 1
		}
	}
	return ans
}

class Solution {
public:
    string longestDupSubstring(string S) {
        string_view longest;
        unordered_set<string_view> set;
        size_t beg = 1;
        size_t end = S.size() - 1;
        while (beg <= end)
        {
            auto len = beg + (end - beg) / 2;
            bool found = false;
            for (size_t i = 0; i != S.size() - len + 1; ++i)
            {
                const auto [it, inserted] = set.emplace(S.data() + i, len);
                if (!inserted)
                {
                    found = true;
                    longest = *it;
                    break;
                }
            }

            if (found)
                beg = len + 1;
            else
                end = len - 1;

            set.clear();
        }

        return {longest.begin(), longest.end()};
    }
};

#include <stdlib.h>
#include <string.h>

#define MAX_STATES 200005

static int nxt[MAX_STATES][26];
static int link_st[MAX_STATES];
static int len_st[MAX_STATES];

char* longestDupSubstring(char* s) {
    int n = (int)strlen(s);
    int sz = 1, last = 1;
    len_st[1] = 0;
    link_st[1] = 0;
    memset(nxt[1], 0, sizeof(nxt[1]));

    int max_len = 0, best_end = 0;

    for (int i = 0; i < n; ++i) {
        int c = s[i] - 'a';
        int cur = ++sz;
        len_st[cur] = len_st[last] + 1;
        memset(nxt[cur], 0, sizeof(nxt[cur]));

        int p = last;
        while (p && !nxt[p][c]) {
            nxt[p][c] = cur;
            p = link_st[p];
        }

        if (!p) {
            link_st[cur] = 1;
        } else {
            int q = nxt[p][c];
            if (len_st[p] + 1 == len_st[q]) {
                link_st[cur] = q;
            } else {
                int clone = ++sz;
                len_st[clone] = len_st[p] + 1;
                memcpy(nxt[clone], nxt[q], sizeof(nxt[q]));
                link_st[clone] = link_st[q];
                while (p && nxt[p][c] == q) {
                    nxt[p][c] = clone;
                    p = link_st[p];
                }
                link_st[q] = link_st[cur] = clone;
            }
        }
        last = cur;

        int l = len_st[link_st[cur]];
        if (l > max_len) {
            max_len = l;
            best_end = i;
        }
    }

    char* res = (char*)malloc(max_len + 1);
    if (max_len > 0) {
        memcpy(res, s + best_end - max_len + 1, max_len);
    }
    res[max_len] = '\0';
    return res;
}

class Solution {
    private static final int MAX_STATES = 60005;
    private static final char[] nxt = new char[MAX_STATES << 5];
    private static final char[] linkSt = new char[MAX_STATES];
    private static final char[] lenSt = new char[MAX_STATES];
    private static final char[] ZERO_ROW = new char[26];

    public String longestDupSubstring(String s) {
        final int n = s.length();
        int sz = 1, last = 1;
        lenSt[1] = 0;
        linkSt[1] = 0;
        System.arraycopy(ZERO_ROW, 0, nxt, 32, 26);

        int maxLen = 0, bestEnd = 0;

        for (int i = 0; i < n; ++i) {
            final int c = s.charAt(i) - 'a';
            final int cur = ++sz;
            lenSt[cur] = (char) (i + 1);
            System.arraycopy(ZERO_ROW, 0, nxt, cur << 5, 26);

            int p = last;
            while (p != 0 && nxt[(p << 5) | c] == 0) {
                nxt[(p << 5) | c] = (char) cur;
                p = linkSt[p];
            }

            if (p == 0) {
                linkSt[cur] = 1;
            } else {
                final int pIdx = (p << 5) | c;
                final int q = nxt[pIdx];
                final int lp = lenSt[p] + 1;
                if (lp == lenSt[q]) {
                    linkSt[cur] = (char) q;
                } else {
                    final int clone = ++sz;
                    lenSt[clone] = (char) lp;
                    System.arraycopy(nxt, q << 5, nxt, clone << 5, 26);
                    linkSt[clone] = linkSt[q];
                    while (p != 0 && nxt[(p << 5) | c] == q) {
                        nxt[(p << 5) | c] = (char) clone;
                        p = linkSt[p];
                    }
                    linkSt[q] = linkSt[cur] = (char) clone;
                }
                if (lp > maxLen) {
                    maxLen = lp;
                    bestEnd = i;
                }
            }
            last = cur;
        }

        return maxLen == 0 ? "" : s.substring(bestEnd - maxLen + 1, bestEnd + 1);
    }
}

class Solution(object):
    def longestDupSubstring(self, s):
        """
        :type s: str
        :rtype: str
        """
        arr = [ord(c) - ord('a') for c in s]
        mod = 2 ** 63 - 1

        def check(L):
            cur_hash = reduce(lambda x, y: (x * 26 + y) % mod, arr[:L], 0)
            seen = {cur_hash}
            for i in range(L, len(s)):
                cur_hash = (cur_hash * 26 + arr[i] - arr[i - L] * pow(26, L, mod)) % mod
                if cur_hash in seen:
                    return i - L + 1
                seen.add(cur_hash)
            return -1

        left, right = 0, len(s) - 1
        ans_pos, ans_len = -1, 0
        while left <= right:
            mid = (left + right) // 2
            cur_ans = check(mid)
            if cur_ans != -1:
                ans_pos = cur_ans
                ans_len = mid
                left = mid + 1
            else:
                right = mid - 1

        if ans_pos == -1:
            return ""
        else:
            return s[ans_pos: ans_pos + ans_len]
